\title{Foundations of the $p$-adic Langlands Correspondence for
$\GL_2(\Qp)$: The Determinant Bridge and Twisting Compatibilities}
\author{Aristotle}
\date{2026-07-24}

\begin{document}

\begin{abstract}
We develop a self-contained algebraic foundation for the two sides of the
$p$-adic Langlands correspondence for $\GL_2(\Qp)$. On the automorphic side we
study the group $\GL_2(K)$ over a field $K$ (specialized to $K=\Qp$), its scalar
center, and the determinant homomorphism $\det:\GL_2(K)\to\Km$. On the Galois
side we study two-dimensional representations $\rho:G\to\GL_2(K)$ of an abstract
group $G$ (a stand-in for the absolute Galois group
$\mathrm{Gal}(\overline{\mathbb{Q}}_p/\Qp)$), their determinant characters, and
their behavior under character twists. We prove: (i) the Cayley--Hamilton
identity $M^2=(\tr M)M-(\det M)I$ for $2\times 2$ matrices, together with the
adjugate identity it implies; (ii) that the determinant $\GL_2(K)\to\Km$ is a
surjective homomorphism with kernel $\SL_2(K)$; (iii) a bijection --- the
abelian, $\GL_1$ shadow of local Langlands --- between characters of $\Km$ and
characters of $\GL_2(K)$ trivial on $\SL_2(K)$; (iv) the centrality of scalar
matrices and the fact that the determinant of $uI$ is $u^2$; and (v) the twisting
compatibility $\det(\chi\otimes\rho)=\chi^2\cdot\det\rho$. All results are
specialized to $K=\Qp$. These statements form a rigid algebraic skeleton onto
which the analytic theory can be attached.
\end{abstract}

\maketitle

\section{Introduction}

The Langlands program predicts deep and precise correspondences between the
arithmetic of Galois representations and the harmonic analysis of automorphic
representations. Its \emph{local} incarnations attach, to representations of the
absolute Galois group of a local field, representations of a reductive group over
that field. The $p$-adic Langlands correspondence for $\GL_2(\Qp)$ --- developed
by Breuil, Colmez, Emerton, Pa\v{s}k\=unas, and others --- is the richest fully
understood case: it establishes a bijection between certain irreducible unitary
$\Qp$-Banach representations of $\GL_2(\Qp)$ and two-dimensional $p$-adic
representations of $\mathrm{Gal}(\overline{\mathbb{Q}}_p/\Qp)$, realized
concretely through Colmez's \emph{Montr\'eal functor}.

The full correspondence is analytic and difficult. Beneath it lies a purely
algebraic layer that is completely explicit and already exhibits the shape of the
general theory: the interplay of trace and determinant on the Galois side, the
determinant homomorphism and central character on the automorphic side, and the
compatibility of the two under twisting. This paper isolates that layer and
proves it in full. Throughout, $K$ denotes a field, $I$ the identity matrix, and
$G$ an abstract group standing in for the absolute Galois group.

\section{Preliminaries and notation}

Let $K$ be a field. We write $M_2(K)$ for the ring of $2\times 2$ matrices over
$K$ and $\GL_2(K)$ for the group of invertible ones; $\Km$ denotes the
multiplicative group of nonzero elements. For $M\in M_2(K)$,
$\tr M=M_{11}+M_{22}$ and $\det M=M_{11}M_{22}-M_{12}M_{21}$. The special linear
group is $\SL_2(K)=\{M\in\GL_2(K):\det M=1\}$. A \emph{character} of a group $H$
valued in a group $A$ is a homomorphism $H\to A$. A \emph{two-dimensional
representation} of $G$ over $K$ is a homomorphism $\rho:G\to\GL_2(K)$. The field
$\Qp$ of $p$-adic numbers is the completion of $\mathbb{Q}$ with respect to the
$p$-adic absolute value; all results proved for a general field $K$ apply to it
verbatim.

\section{The characteristic polynomial of a two-dimensional representation}

\begin{theorem}[Cayley--Hamilton for $2\times2$ matrices]\label{thm:ch}
For every $M\in M_2(K)$,
\[ M^2 = (\tr M)\,M - (\det M)\,I. \]
\end{theorem}

\begin{proof}
The characteristic polynomial of a $2\times 2$ matrix is
$p_M(X)=X^2-(\tr M)X+\det M$. The Cayley--Hamilton theorem gives $p_M(M)=0$,
i.e.\ $M^2-(\tr M)M+(\det M)I=0$, which rearranges to the stated identity.
Directly, with $M=\begin{psmallmatrix}a&b\\c&d\end{psmallmatrix}$, one checks
$M^2=\begin{psmallmatrix}a^2+bc&b(a+d)\\c(a+d)&d^2+bc\end{psmallmatrix}$,
$(\tr M)M=(a+d)M$, and $(\det M)I=(ad-bc)I$; subtracting confirms the identity
entrywise.
\end{proof}

On the Galois side this is the relation satisfied by the image of Frobenius: the
representation is controlled by the trace and determinant of Frobenius, the
coefficients of the characteristic polynomial.

\begin{corollary}[Adjugate identity]\label{cor:adj}
For every $M\in M_2(K)$,
\[ M\big((\tr M)\,I - M\big) = (\det M)\,I. \]
If $\det M\neq0$ then $M$ is invertible with
$M^{-1}=\tfrac{1}{\det M}\big((\tr M)I-M\big)$.
\end{corollary}

\begin{proof}
Expand and apply Theorem~\ref{thm:ch}:
$M((\tr M)I-M)=(\tr M)M-M^2=(\tr M)M-((\tr M)M-(\det M)I)=(\det M)I$. Dividing by
the nonzero scalar $\det M$ gives the inverse formula.
\end{proof}

\section{The determinant bridge and the abelian correspondence}

\begin{definition}
For $u\in\Km$, let $\mathrm{diag}(u,1)$ denote the diagonal element of $\GL_2(K)$
with diagonal entries $u$ and $1$; its inverse is $\mathrm{diag}(u^{-1},1)$.
\end{definition}

\begin{lemma}\label{lem:diagdet}
$\det\mathrm{diag}(u,1)=u$.
\end{lemma}

\begin{proof}
The determinant of a diagonal $2\times 2$ matrix is the product of its diagonal
entries: $u\cdot 1=u$.
\end{proof}

\begin{theorem}[The determinant is surjective]\label{thm:surj}
The determinant homomorphism $\det:\GL_2(K)\to\Km$ is surjective.
\end{theorem}

\begin{proof}
Given $u\in\Km$, the element $\mathrm{diag}(u,1)$ has determinant $u$ by
Lemma~\ref{lem:diagdet}.
\end{proof}

\begin{proposition}[Kernel of the determinant]\label{prop:ker}
An element $g\in\GL_2(K)$ lies in $\ker\det$ iff $\det g=1$; that is,
$\ker\det=\SL_2(K)$.
\end{proposition}

\begin{proof}
$g\in\ker\det$ iff $\det g$ is the identity of $\Km$, i.e.\ $\det g=1$, the
defining condition of $\SL_2(K)$.
\end{proof}

\begin{theorem}[Abelian local Langlands, $\GL_1$ shadow]\label{thm:abelian}
Let $A$ be any group. Precomposition with $\det$ defines a bijection
\[
\big(\Km\to A\big)\;\xrightarrow{\ \sim\ }\;
\big\{\,f:\GL_2(K)\to A \text{ a homomorphism with } \SL_2(K)\subseteq\ker f\,\big\},
\qquad \chi\mapsto\chi\circ\det.
\]
Equivalently, every homomorphism $\GL_2(K)\to A$ trivial on $\SL_2(K)$ factors
uniquely through the determinant.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:surj} the determinant is a surjective homomorphism, and by
Proposition~\ref{prop:ker} its kernel is $\SL_2(K)$; hence $\det$ realizes $\Km$
as $\GL_2(K)/\SL_2(K)$. The universal property of the quotient identifies
homomorphisms out of $\GL_2(K)$ trivial on $\SL_2(K)$ with homomorphisms out of
$\Km$, via precomposition with $\det$. Concretely: injectivity follows from
right-cancellability of the surjection $\det$; surjectivity follows because a map
$f$ trivial on $\ker\det$ descends to $\chi(u):=f(g)$ for any $g$ with $\det g=u$,
a well-defined homomorphism with $\chi\circ\det=f$.
\end{proof}

\begin{corollary}[Injectivity of twisting]\label{cor:inj}
The map $\chi\mapsto\chi\circ\det$ from characters of $\Km$ to characters of
$\GL_2(K)$ is injective.
\end{corollary}

\begin{proof}
Immediate from right-cancellability of the surjection $\det$.
\end{proof}

Under local class field theory, characters of $\Qp^{\times}$ are identified with
characters of the abelianized Weil group, i.e.\ one-dimensional Galois
representations. Theorem~\ref{thm:abelian} is therefore the local Langlands
correspondence for $\GL_1$.

\section{The center: scalar matrices and the central character}

\begin{definition}[Scalar embedding]
Let $\iota:\Km\to\GL_2(K)$ send $u\mapsto uI$.
\end{definition}

$\iota$ is a homomorphism since $(uv)I=(uI)(vI)$ and $1\cdot I=I$.

\begin{proposition}[Determinant of a scalar]\label{prop:scalardet}
For $u\in\Km$, $\det(\iota(u))=\det(uI)=u^2$.
\end{proposition}

\begin{proof}
$uI$ is diagonal with both diagonal entries $u$, so its determinant is
$u\cdot u=u^2$.
\end{proof}

\begin{proposition}[Centrality]\label{prop:central}
For every $u\in\Km$ and $g\in\GL_2(K)$, $\iota(u)g=g\iota(u)$.
\end{proposition}

\begin{proof}
For any matrix $N$, $(uI)N=uN=N(uI)$ entrywise; restrict to invertible $g$.
\end{proof}

\section{Twisting two-dimensional representations}

\begin{definition}[Determinant character]
For $\rho:G\to\GL_2(K)$, its \emph{determinant character} is
$\det\rho:=\det\circ\,\rho:G\to\Km$.
\end{definition}

\begin{definition}[Twist]
For $\rho:G\to\GL_2(K)$ and $\chi:G\to\Km$, the \emph{twist} is
$(\chi\otimes\rho)(g):=\chi(g)\rho(g)=\iota(\chi(g))\rho(g)$.
\end{definition}

\begin{proposition}\label{prop:twisthom}
The twist $\chi\otimes\rho$ is a homomorphism $G\to\GL_2(K)$.
\end{proposition}

\begin{proof}
$(\chi\otimes\rho)(1)=\chi(1)\rho(1)=I$, and for $g,h\in G$, using centrality
(Proposition~\ref{prop:central}),
\[
(\chi\otimes\rho)(gh)=\iota(\chi(g)\chi(h))\rho(g)\rho(h)
=\iota(\chi(g))\rho(g)\,\iota(\chi(h))\rho(h)
=(\chi\otimes\rho)(g)(\chi\otimes\rho)(h).
\]
\end{proof}

\begin{theorem}[Twisting law for determinants]\label{thm:twist}
For every $\chi:G\to\Km$, every $\rho:G\to\GL_2(K)$, and every $g\in G$,
\[ \det(\chi\otimes\rho)(g)=\chi(g)^2\cdot\det\rho(g),\qquad\text{i.e.}\qquad
\det(\chi\otimes\rho)=\chi^2\cdot\det\rho. \]
\end{theorem}

\begin{proof}
By multiplicativity of the determinant,
$\det(\chi\otimes\rho)(g)=\det(\iota(\chi(g))\rho(g))
=\det(\iota(\chi(g)))\det(\rho(g))$. By
Proposition~\ref{prop:scalardet}, $\det(\iota(\chi(g)))=\chi(g)^2$, giving the
result.
\end{proof}

The exponent $2$ is the numerical fingerprint of two-dimensionality: the
determinant of a two-dimensional Galois representation matches the central
character of its automorphic partner, and both transform by $\chi^2$ under
twisting by $\chi$.

\section{Specialization to $\Qp$}

\begin{theorem}\label{thm:padic}
Let $p$ be a prime. Then:
\begin{enumerate}
\item Every $M\in M_2(\Qp)$ satisfies $M^2=(\tr M)M-(\det M)I$.
\item $\det:\GL_2(\Qp)\to\Qp^{\times}$ is a surjective homomorphism with kernel
$\SL_2(\Qp)$.
\item For any group $A$, characters $\GL_2(\Qp)\to A$ trivial on $\SL_2(\Qp)$ are
in bijection with characters $\Qp^{\times}\to A$, via $\chi\mapsto\chi\circ\det$.
\item For every $\chi:G\to\Qp^{\times}$, $\rho:G\to\GL_2(\Qp)$, and $g\in G$,
$\det(\chi\otimes\rho)(g)=\chi(g)^2\det\rho(g)$.
\end{enumerate}
\end{theorem}

\begin{proof}
Each statement is the corresponding general result of the previous sections
(Theorem~\ref{thm:ch}, Theorems~\ref{thm:surj}/\ref{thm:abelian} with
Proposition~\ref{prop:ker}, and Theorem~\ref{thm:twist}) applied to $K=\Qp$.
\end{proof}

\section{Applications and future directions}

The abelian correspondence (Theorem~\ref{thm:abelian}) is the $\GL_1$ case of
local Langlands stated as the universal property of the determinant. The twisting
law (Theorem~\ref{thm:twist}) is the central-character compatibility any
normalization of the $p$-adic correspondence must respect. These algebraic
identities are the invariants any correspondence must preserve, before any
topology is introduced.

Natural next steps: (1) topologize the objects (unitary $\Qp$-Banach
representations of $\GL_2(\Qp)$ and their unit balls; continuous two-dimensional
Galois representations); (2) construct the Montr\'eal functor from
$(\varphi,\Gamma)$-modules and verify it carries the determinant character to the
central character; (3) characterize irreducible unitary Banach representations and
prove the bijection with irreducible two-dimensional Galois representations; and
(4) establish compatibility with reduction mod $p$ and with deformation theory.

