from fractions import Fraction
from typing import Tuple

Matrix = Tuple[Tuple[Fraction, Fraction], Tuple[Fraction, Fraction]]

def trace(m: Matrix) -> Fraction:
    return m[0][0] + m[1][1]

def det(m: Matrix) -> Fraction:
    return m[0][0] * m[1][1] - m[0][1] * m[1][0]

def matmul(a: Matrix, b: Matrix) -> Matrix:
    return tuple(tuple(sum(a[i][k] * b[k][j] for k in range(2))
                       for j in range(2)) for i in range(2))

def scale(s: Fraction, m: Matrix) -> Matrix:
    return tuple(tuple(s * m[i][j] for j in range(2)) for i in range(2))

def sub(a: Matrix, b: Matrix) -> Matrix:
    return tuple(tuple(a[i][j] - b[i][j] for j in range(2)) for i in range(2))

I: Matrix = ((Fraction(1), Fraction(0)), (Fraction(0), Fraction(1)))

def verify(m: Matrix) -> None:
    ch = sub(matmul(m, m), sub(scale(trace(m), m), scale(det(m), I)))
    print("Cayley-Hamilton residual:", ch)
    adj = sub(scale(trace(m), I), m)
    print("M * adj = det*I:", matmul(m, adj) == scale(det(m), I))
    inv = scale(Fraction(1) / det(m), adj)
    print("M * inv = I:", matmul(m, inv) == I)

if __name__ == "__main__":
    verify(((Fraction(2), Fraction(3)), (Fraction(1), Fraction(4))))

from fractions import Fraction
from typing import Tuple

Matrix = Tuple[Tuple[Fraction, Fraction], Tuple[Fraction, Fraction]]

def det(m: Matrix) -> Fraction:
    return m[0][0] * m[1][1] - m[0][1] * m[1][0]

def diag_gl(u: Fraction) -> Matrix:
    return ((u, Fraction(0)), (Fraction(0), Fraction(1)))

def in_sl2(m: Matrix) -> bool:
    return det(m) == 1

if __name__ == "__main__":
    for u in (Fraction(5), Fraction(-3), Fraction(7, 2)):
        g = diag_gl(u)
        print(f"witness for u={u}: det(diag(u,1)) = {det(g)} (onto: {det(g) == u})")
    samples = {
        "[[1,1],[0,1]]": ((Fraction(1), Fraction(1)), (Fraction(0), Fraction(1))),
        "[[2,3],[1,4]]": ((Fraction(2), Fraction(3)), (Fraction(1), Fraction(4))),
    }
    for name, m in samples.items():
        print(f"{name}: det={det(m)}, in SL_2 = {in_sl2(m)}")

import cmath
from typing import Tuple, List

Matrix = Tuple[Tuple[complex, complex], Tuple[complex, complex]]

def det(m: Matrix) -> complex:
    return m[0][0] * m[1][1] - m[0][1] * m[1][0]

def scale(s: complex, m: Matrix) -> Matrix:
    return tuple(tuple(s * m[i][j] for j in range(2)) for i in range(2))

def rho(g: int, n: int) -> Matrix:
    # rotation by 2*pi*g/n : a genuine order-dividing-n representation
    theta = 2 * cmath.pi * g / n
    c, s = cmath.cos(theta), cmath.sin(theta)
    return ((c, -s), (s, c))

def chi(g: int, n: int) -> complex:
    return cmath.exp(2j * cmath.pi * g / n)

if __name__ == "__main__":
    n = 6
    max_err = 0.0
    for g in range(n):
        twisted = scale(chi(g, n), rho(g, n))
        lhs = det(twisted)
        rhs = chi(g, n) ** 2 * det(rho(g, n))
        max_err = max(max_err, abs(lhs - rhs))
        print(f"g={g}: det(twist)={lhs:.4f}, chi^2 det rho={rhs:.4f}")
    print(f"max deviation from twisting law: {max_err:.2e}")

