function INVERSE_2x2(M):
    t <- M[0][0] + M[1][1]            # trace
    d <- M[0][0]*M[1][1] - M[0][1]*M[1][0]   # determinant
    if d == 0:
        raise 'singular matrix'
    A <- t * I - M                     # adjugate
    return (1 / d) * A                 # M^{-1}

function DESCEND_THROUGH_DET(f, u):
    # f: GL_2(K) -> A trivial on SL_2(K);  u in K^x
    g <- diag(u, 1)          # a preimage of u under det
    return f(g)              # = chi(u), independent of the preimage

function LIFT_CHARACTER(chi):
    # inverse direction: chi: K^x -> A  |->  f = chi . det
    return (lambda g: chi(det(g)))

