from fractions import Fraction
from typing import Callable, Tuple

Matrix = Tuple[Tuple[Fraction, Fraction], Tuple[Fraction, Fraction]]

def det(m: Matrix) -> Fraction:
    return m[0][0] * m[1][1] - m[0][1] * m[1][0]

def diag(u: Fraction) -> Matrix:
    return ((u, Fraction(0)), (Fraction(0), Fraction(1)))

def descend_through_det(f: Callable[[Matrix], Fraction], u: Fraction) -> Fraction:
    """Reconstruct chi(u) from a GL_2-character f trivial on SL_2."""
    return f(diag(u))

def lift_character(chi: Callable[[Fraction], Fraction]) -> Callable[[Matrix], Fraction]:
    """Lift a character of K^x to the GL_2-character chi . det."""
    return lambda g: chi(det(g))

if __name__ == "__main__":
    chi = lambda u: u * u            # sample character K^x -> K^x
    f = lift_character(chi)
    for u in (Fraction(2), Fraction(5), Fraction(3, 2)):
        print(u, descend_through_det(f, u), chi(u))
